  let total = 0;
  const result = [];
  // Walk backwards, always keep system + last few messages
  for (let i = messages.length - 1; i >= 0; i--) {
    const msg = messages[i];
    const size = JSON.stringify(msg.content || "").length;
    if (total + size > maxChars && i > 0) break;
    total += size;
    result.unshift(msg);
  }
